"""gen_vocab.py [FILE] : the `rainbow` entry of drivers/fault-vocabulary.json, from the maker's own message table (`skynet_rainbow/codes.py`, itself generated by `sim/gen_codes.py`) and the packet document's tables.

    PYTHONPATH=bindings/python:drivers/rainbow python3 drivers/rainbow/sim/gen_vocab.py

Adds the entry, or replaces it where it is already the last one in the file (it is written last, and the file is spliced, not re-dumped, so that every other entry stays as it was, byte for byte).
"""
import json
import os
import sys

from skynet_rainbow import frames

HERE = os.path.dirname(os.path.abspath(__file__))
TARGET = sys.argv[1] if len(sys.argv) > 1 else os.path.join(HERE, "..", "..", "fault-vocabulary.json")

JOINT_NAMES = ("Base", "Shoulder", "Elbow", "Wrist1", "Wrist2", "Wrist3")
CODES = frames.CODES
assert len(CODES) == 606 and min(CODES) == 0 and max(CODES) == 605 and frames.ESTOP_CODES <= set(CODES)

TABLE_SOURCE = ("Rainbow Robotics' own client `rbpodo` (Apache-2.0, https://github.com/RainbowRobotics/rbpodo, commit f6ef41ad), `include/rbpodo/error_code.hpp`: `ErrorCodeMessage`, 606 codes (0 to 605), each with a Korean and an English text, of which "
                "the English is used here. The table was generated from that file (`sim/gen_codes.py`), not typed, and `layout_check.py` runs the maker's client against this repository's simulated controller. Read, and run against that "
                "simulator; no Rainbow arm and no Rainbow control box was reached. The classes are this driver's reading of the texts and not the maker's: the table says neither which of its codes arrive as an `error` and which as a "
                "`warn` or an `info`, nor what the controller does with a command while one is held.")
PACKET_SOURCE = ("Rainbow Robotics' own packet document, `reqdata_Structure` 6.10 (the state packet a `reqdata` returns on the data port, 580 bytes), which `layout_check.py` holds the driver's offsets to by running the maker's client on the "
                 "same bytes. Read, and run against this repository's simulated controller; no Rainbow arm and no Rainbow control box was reached.")

PROBES_CODE = [606, 700, 1000, 9999, 65535, 2147483647]
assert not set(PROBES_CODE) & set(CODES)

error_codes = {str(n): {"name": text, "class": "estop" if n in frames.ESTOP_CODES else "fault"} for n, text in sorted(CODES.items())}
warn_codes = {str(n): {"name": text, "class": "degraded"} for n, text in sorted(CODES.items())}

sos_codes = {"0": {"name": "0 = None", "class": "ok"}}
sos_codes.update({str(n): {"name": f"{n} = {text}", "class": "fault"} for n, text in sorted(frames.SOS_FLAGS.items())})
ems_codes = {"0": {"name": "0 = None", "class": "ok"}}
ems_codes.update({str(n): {"name": f"{n} = {text}", "class": "fault"} for n, text in sorted(frames.EMS_FLAGS.items())})

joint_codes = {"0": {"name": "no error bit in any joint's word (bits 0 to 3, the FET, RUN, INIT and MODE state, are not errors)", "class": "ok"}}
for joint, joint_name in enumerate(JOINT_NAMES):
    for bit, bit_name in sorted(frames.JOINT_ERROR_BITS.items()):
        joint_codes[str(joint << 8 | bit)] = {"name": f"{joint_name} (joint {joint}) bit {bit}: {bit_name}", "class": "fault"}

estop_text = ", ".join(str(n) for n in sorted(frames.ESTOP_CODES))
entry = {
    "subject": "drivers/rainbow/faultvocab.py",
    "vocabularies": {
        "error_code": {
            "channel": ("the controller's `error[code][N]` line on the command port (5000): the controller says an error once, the bridge holds each code it reads until the `clear_faults` motion acknowledges it (refused while the packet "
                        "still shows a cause), and the fault word is the first held code, a stop's before any other"),
            "source": TABLE_SOURCE,
            "kind": "alarm",
            "why": (f"an `error` line is the controller reporting something it did not do or cannot do, and the one table it uses for `info`, `warn` and `error` does not say which code goes on which channel, so every code that arrives as an `error` "
                    f"is read as the arm not doing what it is told: `fault` (FAULT and DEGRADED, commands refused, because an answer of OK to a command the controller is ignoring is success the driver did not have). Eleven are about the "
                    f"stop chain in the maker's own words ({estop_text}: the Safety switches 'open or closed', the EMS 1 and 2, PRS, HSS and SSS switches, 'powered off by the ... Safety switch', and 60 'Control Box GP Switch Error Check "
                    f"Protective stop connector') and are `estop`. Codes whose text is about the safety parameters, walls and polygons (222 to 240, 496, 497, 520, 521) or an 'emergency direct teach' (259, 297, 490) are not the stop "
                    f"chain, and on the `error` channel they stay `fault`. Acknowledging is the `clear_faults` motion, which is a person's to ask for; a stop chain is closed at the control box."),
            "codes": error_codes,
            "unmapped": "fault",
            "unmapped_because": ("an `error` line whose code is in no table is an error from a controller newer than this table: it is still the controller saying it did not do something, so the arm is read as not doing what it is told, "
                                 "and never as healthy."),
            "probes": PROBES_CODE,
            "fault_code": "verbatim",
        },
        "warn_code": {
            "channel": ("the controller's `warn[code][N]` line on the command port (5000): the controller says a warning once, after it has acknowledged the command it is about; the bridge shows DEGRADED for two seconds with the code as "
                        "the fault word, and refuses the next command once (EINVAL, naming the warning) so that the person sending commands hears it"),
            "source": TABLE_SOURCE,
            "kind": "warning",
            "why": ("a `warn` line is the controller's advisory channel: it carries on, so the arm is `degraded` (DEGRADED alone, commands taken) and never a fault. The table is the one the `error` channel uses and does not say which of its codes "
                    "arrive as warnings, so none is singled out, and one that is about the stop chain is no stop when it comes as a warning. The bridge tells the person at the next command by refusing it once, as the controller's answer to "
                    "the command before it; the contract's command is sent again in that case (the subject says so), and a refusal that goes on would fail it."),
            "codes": warn_codes,
            "unmapped": "degraded",
            "unmapped_because": ("a warning code in no table is a warning from a controller newer than this table, which the controller runs on through: it is not read as healthy, because the driver cannot say what it is about, and not as a stop, "
                                 "because the channel is advisory."),
            "probes": PROBES_CODE,
            "fault_code": "verbatim",
        },
        "sos_flag": {
            "channel": "`op_stat_sos_flag` in the state packet (offset 448, an integer, the low six bits valid), read in every packet",
            "source": PACKET_SOURCE,
            "kind": "alarm",
            "why": ("the document calls it the 'robot arm device error code during operation' and lists twelve; it does not say what the arm does with a command while one is set, so none is sent: a nonzero flag is `fault` (FAULT and DEGRADED, "
                    "commands refused). None of the twelve is the stop chain in its words, so none is `estop`. The fault word is the flag in a band of its own above every code of the maker's message table."),
            "codes": sos_codes,
            "unmapped": "fault",
            "unmapped_because": ("a device error number the document does not list (13 to 63) is a device error from a controller newer than this document, and a flag of any value is a device saying something is wrong: it is not read as healthy. "
                                 "The document says only the low six bits are valid, so a value from 64 up is read as its low six bits and is not probed."),
            "probes": [13, 14, 20, 33, 63],
            "fault_code": "derived",
            "fault_code_is": "65536 plus the flag",
        },
        "ems_flag": {
            "channel": "`op_stat_ems_flag` in the state packet (offset 460, an integer, the low six bits valid), read in every packet",
            "source": PACKET_SOURCE,
            "kind": "alarm",
            "why": ("the document calls it the 'software (kinematics) emergency stop situation' and lists four: arm stretch, Cartesian limit, joint limit, un-solvable. The words are about a pose the controller's own software would not take, "
                    "not about the stop chain, so a nonzero flag is `fault` (commands refused) and not `estop`. The fault word is the flag in a band of its own."),
            "codes": ems_codes,
            "unmapped": "fault",
            "unmapped_because": ("a software stop cause the document does not list (5 to 63) is a stop from a controller newer than this document: it is not read as healthy. Only the low six bits are valid, so a value from 64 up is not probed."),
            "probes": [5, 6, 10, 33, 63],
            "fault_code": "derived",
            "fault_code_is": "131072 plus the flag",
        },
        "collision": {
            "channel": "`op_stat_collision_occur` in the state packet (offset 444, an integer, the low two bits valid), read in every packet",
            "source": PACKET_SOURCE,
            "kind": "alarm",
            "why": ("the document says 'whether out-collision is detected (0 or 1)'. A detected collision has stopped the arm's program (code 3 of the maker's table is 'Program is Stopped because of Collision-Detection'), so it is `fault`; "
                    "the `resume` motion with `after=collision` is how a person goes on. The fault word is the value in a band of its own."),
            "codes": {"0": {"name": "0 = no out-collision detected", "class": "ok"}, "1": {"name": "1 = out-collision detected", "class": "fault"}},
            "unmapped": "fault",
            "unmapped_because": "the document lists 0 and 1, and a value of 2 or 3 is a bit the document does not name: it is not read as healthy.",
            "no_probes": ("the document says only the low two bits are valid, so the only values outside the table are 2 and 3, fewer than the three the contract wants and each of them a single bit the document does not name; "
                          "`selftest.py` holds both."),
            "probes": [],
            "fault_code": "derived",
            "fault_code_is": "196608 plus the value",
        },
        "joint_info": {
            "channel": ("`jnt_info[6]` in the state packet (offset 372, six integers, one a joint), read in every packet. The code here is the joint (0 for the base to 5 for the third wrist) times 256 plus the bit, the one error bit set in "
                        "that joint's word"),
            "source": PACKET_SOURCE,
            "kind": "alarm",
            "why": ("each of bits 4 to 15 of a joint's word is, in the document's words, an encoder error (Nonius, low battery, calibration mode, multi-turn) or a joint error state (JAM, CUR, BIG, INP, FLT, TMP, PS1, PS2), and a joint "
                    "that reports one is not doing what it is told: `fault` (commands refused). The fault word is the joint and the bit in a band of its own, so that the black box says which joint and which error."),
            "codes": joint_codes,
            "unmapped": "fault",
            "unmapped_because": "every bit of the word that the document names is in the table, and an unlisted one is not a code but a reserved bit.",
            "no_probes": ("the word is a bitset of which every bit from 0 to 15 is named (0 to 3 are state, 4 to 15 errors) and bits 16 to 31 are 'reserved' by the document: there is no code outside the table to probe. "
                          "The reserved bits are in `not_covered`."),
            "probes": [],
            "fault_code": "derived",
            "fault_code_is": "262144 plus the joint times 256 plus the bit",
        },
        "sos_state": {
            "channel": "`information_chunk_1` bit 12 in the state packet (offset 344), 'Is SOS State', read in every packet",
            "source": PACKET_SOURCE,
            "kind": "alarm",
            "why": ("the document names the state and not what the arm does in it, so a controller in its SOS state is read as not doing what it is told, which is the safe reading: `fault` (commands refused), and not `estop`, because "
                    "the document does not say it is the stop chain. The fault word is one value in a band of its own."),
            "codes": {"0": {"name": "bit 12 clear: not in the SOS state", "class": "ok"}, "1": {"name": "bit 12 set: Is SOS State", "class": "fault"}},
            "unmapped": "fault",
            "unmapped_because": "the field is one bit, so there is no value outside the table, and a state the document names but does not describe is not read as healthy.",
            "no_probes": "the field is one bit of a word and has two values, both in the table: there is no code outside it to probe.",
            "probes": [],
            "fault_code": "derived",
            "fault_code_is": "393216, one value for the state",
        },
        "mode": {
            "channel": "`real_vs_simulation_mode` in the state packet (offset 404, an integer, the low four bits valid), read in every packet",
            "source": PACKET_SOURCE,
            "kind": "alarm",
            "why": ("the document lists 0 for a real robot and 1 for the simulation. The subject opens the bridge with `simulator: true`, so the simulation is the mode that takes commands (`ok`); the other listed mode is not a state of the "
                    "arm but a disagreement between the controller and what the operator said, and is in `not_covered`. A value the document does not list (2 to 15) is a state nobody here has read about: `fault`, with the value in a band "
                    "of its own above every code of the maker's table."),
            "codes": {"1": {"name": "1 = Simulation mode (the mode `simulator: true` asks for)", "class": "ok"}},
            "unmapped": "fault",
            "unmapped_because": "a mode the document does not list is a state of the controller that this table has no word for; it is not read as healthy.",
            "probes": [2, 3, 4, 8, 15],
            "fault_code": "derived",
            "fault_code_is": "327680 plus the mode",
        },
    },
    "not_covered": [
        {"what": "a controller in the mode the operator did not ask for (mode 0 under `simulator: true`, mode 1 under `simulator: false`), an arm that is not activated (`init_state_info` below 6, in the real mode), and one that is paused (the task state or `op_stat_soft_estop_occur`)",
         "why": ("in each the arm takes no motion command and none is a fault: the driver reports DEGRADED and refuses the command (EPERM, naming the motion that changes the state: `set_mode`, `activate`, `resume`). The contract has no class for that: "
                 "its `degraded` takes commands and its `fault` sets FAULT. `selftest.py` holds each of them.")},
        {"what": "bits 16 to 31 of a joint's `jnt_info` word, 'reserved' in the document",
         "why": ("the document gives them no meaning, so reading one as an error would be this driver's invention, and the driver does not read them. A reserved bit that a later controller gives a meaning is a change the probes of this table "
                 "cannot reach.")},
        {"what": "the control box's E-Stop states 1 and 2 (`information_chunk_1` bits 3 and 5) and `op_stat_self_collision`",
         "why": ("the document says which bit is which switch and not which value is a pressed stop, and gives the self-collision field a bit table whose meaning of 'last out-collision state' is not said: reading either would be this driver's "
                 "own invention. A stop is read from the error codes, where the maker names it (253 to 258, 485 to 488, 60). `status` reports the two bits as sent.")},
        {"what": "the controller's own emergency stop wiring",
         "why": ("the controller's stop is a hardware chain, and this driver sees it only as an error code or a changed field after the fact. The driver's own stop is `task stop` with a latch of its own, and says so: it is not the chain, "
                 "and the controller was seen to leave its stop unlatched.")},
    ],
}

text = open(TARGET, encoding="utf-8", newline="").read()
doc = json.loads(text)
tail = "\n  }\n}"
assert text.endswith(tail) or text.endswith(tail + "\n"), "the file does not end the way the splice expects"
end = text.rindex(tail)
marker = ',\n    "rainbow": '
if "rainbow" in doc["drivers"]:
    assert list(doc["drivers"])[-1] == "rainbow", "rainbow is in the file and is not the last entry: remove it by hand"
    start = text.rindex(marker)
    text = text[:start] + text[end:]
    end = text.rindex(tail)
block = json.dumps(entry, indent=2, ensure_ascii=False)
block = "\n".join(("    " + line) if line else line for line in block.splitlines())
new = text[:end] + marker + block.lstrip() + text[end:]
json.loads(new)
with open(TARGET, "w", encoding="utf-8", newline="\n") as handle:
    handle.write(new)
print("rainbow:", len(error_codes), "error codes,", len(warn_codes), "warn codes,", len(sos_codes) - 1, "device errors,", len(joint_codes) - 1, "joint bits")
